CREATE INDEX IF NOT EXISTS flow_ts_idx           ON flow (flow_ts);
CREATE INDEX IF NOT EXISTS flow_application_idx  ON flow (application);
CREATE INDEX IF NOT EXISTS flow_convo_key_idx    ON flow (convo_key);
CREATE INDEX IF NOT EXISTS flow_exporter_idx     ON flow (exporter_node_id);
CREATE INDEX IF NOT EXISTS flow_document_gin_idx ON flow USING gin (document);

CREATE OR REPLACE FUNCTION flow_maintain_partitions(retention_days int DEFAULT 14,
                                                    premake_days int DEFAULT 3)
RETURNS void AS $$
DECLARE
    d          date;
    part_name  text;
    cutoff     date := (now()::date - make_interval(days => retention_days))::date;
    child      record;
    child_date date;
BEGIN
    -- Pre-create today + upcoming daily partitions.
    FOR i IN 0..premake_days LOOP
        d := (now()::date + i);
        part_name := format('flow_p%s', to_char(d, 'YYYYMMDD'));
        IF NOT EXISTS (SELECT 1 FROM pg_class WHERE relname = part_name) THEN
            BEGIN
                EXECUTE format(
                    'CREATE TABLE %I PARTITION OF flow FOR VALUES FROM (%L) TO (%L)',
                    part_name, d::timestamptz, (d + 1)::timestamptz);
            EXCEPTION WHEN others THEN
                RAISE NOTICE 'flow_maintain_partitions: could not create %: %', part_name, SQLERRM;
            END;
        END IF;
    END LOOP;

    -- Drop partitions whose day is older than the retention cutoff.
    FOR child IN
        SELECT c.relname AS relname
        FROM pg_inherits i
        JOIN pg_class c ON c.oid = i.inhrelid
        JOIN pg_class p ON p.oid = i.inhparent
        WHERE p.relname = 'flow' AND c.relname ~ '^flow_p[0-9]{8}$'
    LOOP
        child_date := to_date(right(child.relname, 8), 'YYYYMMDD');
        IF child_date < cutoff THEN
            EXECUTE format('DROP TABLE IF EXISTS %I', child.relname);
        END IF;
    END LOOP;
END;
$$ LANGUAGE plpgsql;
